<section class="dash-card" id="profile"><div class="card-title"><h2>پروفایل حرفه‌ای من</h2><span>اطلاعات عمومی</span></div><form method="post" action="<?=url('/dashboard/freelancer/profile')?>"><?=csrf_field()?><div class="form-row"><label>نام نمایشی<input name="display_name" value="<?=e($profile['display_name']??'')?>" required></label><label>نام کاربری<input name="username" value="<?=e($profile['username']??'')?>" required></label></div><label>عنوان شغلی<input name="headline" value="<?=e($profile['headline']??'')?>" placeholder="مثلاً طراح محصول"></label><label>درباره من<textarea name="bio" rows="4"><?=e($profile['bio']??'')?></textarea></label><div class="form-row"><label>نرخ ساعتی<input type="number" name="hourly_rate" min="0" step=".01" value="<?=e($profile['hourly_rate']??'')?>"></label><label>منطقه زمانی<input name="timezone" value="<?=e($profile['timezone']??'UTC')?>"></label></div><label>وضعیت همکاری<select name="availability"><option value="available">آماده همکاری</option><option value="busy">مشغول</option><option value="unavailable">فعلاً در دسترس نیستم</option></select></label><button class="button" type="submit">ذخیره پروفایل</button></form></section>